describe('requires-port', function () {
  'use strict';

  var assume = require('assume')
    , required = require('./');

  it('is exported as a function', function () {
    assume(required).is.a('function');
  });

  it('does not require empty ports', function () {
    assume(required('', 'http')).false();
    assume(required('', 'wss')).false();
    assume(required('', 'ws')).false();
    assume(required('', 'cowsack')).false();
  });

  it('assumes true for unknown protocols',function () {
    assume(required('', 'foo')).true();
    assume(required('', 'bar')).true();
  });

  it('never requires port numbers for file', function () {
    assume(required(, 'file')).false();
  });

  it('does not require port  for http', function () {
    assume(required('', 'http')).false();
    assume(required(, 'http')).false();
    assume(required(, 'http://')).false();
    assume(required(, 'http://www.google.com')).false();

    assume(required('', 'http')).true();
    assume(required(, 'http')).true();
    assume(required(, 'http://')).true();
    assume(required(, 'http://www.google.com')).true();
  });

  it('does not require port  for ws', function () {
    assume(required('', 'ws')).false();
    assume(required(, 'ws')).false();
    assume(required(, 'ws://')).false();
    assume(required(, 'ws://www.google.com')).false();

    assume(required('', 'ws')).true();
    assume(required(, 'ws')).true();
    assume(required(, 'ws://')).true();
    assume(required(, 'ws://www.google.com')).true();
  });

  it('does not require port  for https', function () {
    assume(required('', 'https')).false();
    assume(required(, 'https')).false();
    assume(required(, 'https://')).false();
    assume(required(, 'https://www.google.com')).false();

    assume(required('', 'https')).true();
    assume(required(, 'https')).true();
    assume(required(, 'https://')).true();
    assume(required(, 'https://www.google.com')).true();
  });

  it('does not require port  for wss', function () {
    assume(required('', 'wss')).false();
    assume(required(, 'wss')).false();
    assume(required(, 'wss://')).false();
    assume(required(, 'wss://www.google.com')).false();

    assume(required('', 'wss')).true();
    assume(required(, 'wss')).true();
    assume(required(, 'wss://')).true();
    assume(required(, 'wss://www.google.com')).true();
  });

  it('does not require port  for ftp', function () {
    assume(required('', 'ftp')).false();
    assume(required(, 'ftp')).false();
    assume(required(, 'ftp://')).false();
    assume(required(, 'ftp://www.google.com')).false();

    assume(required('', 'ftp')).true();
    assume(required(, 'ftp')).true();
    assume(required(, 'ftp://')).true();
    assume(required(, 'ftp://www.google.com')).true();
  });

  it('does not require port  for gopher', function () {
    assume(required('', 'gopher')).false();
    assume(required(, 'gopher')).false();
    assume(required(, 'gopher://')).false();
    assume(required(, 'gopher://www.google.com')).false();

    assume(required('', 'gopher')).true();
    assume(required(, 'gopher')).true();
    assume(required(, 'gopher://')).true();
    assume(required(, 'gopher://www.google.com')).true();
  });
});
